        "cite": "Vasari, Lives of the Most Eminent Painters Sculptors and Architects, trans. Gaston du C. de Vere, Vol. 2 (1912); Project Gutenberg #25759.",
        "url": "https://www.gutenberg.org/files/25759/25759-h/25759-h.htm#Page_27",
