const $ = (s, r=document) => r.querySelector(s);
let openArtist = null;
let pxPerYear = 14;

const PALETTE = {
  painting: ['#3d5a45', '#4f7358', '#2f4a38', '#5a8062', '#456650', '#6b8f72', '#334f3c', '#587a5e'],
  sculpture: ['#8a4b32', '#a35a3c', '#734028', '#b56a48', '#935540', '#7a3f2a', '#c17a55', '#6b3824'],
  architecture: ['#2a3d6b', '#3a5080', '#243556', '#4a6294', '#334870', '#1f2f55', '#5a72a0', '#2f4470'],
  antiquity: ['#a6863a', '#c4a35a', '#8a7030', '#b89648'],
  music: ['#5a3d6b', '#6e4d82', '#4a3258', '#7a5a94', '#513868', '#8668a0']
};
const colorCursor = {painting:0, sculpture:0, architecture:0, antiquity:0, music:0};

function colorFor(medium){
  const arr = PALETTE[medium] || PALETTE.painting;
  const i = colorCursor[medium] % arr.length;
  colorCursor[medium]++;
  return arr[i];
}

function yearRange(){
  const decades = (DATA.decades || []).slice().sort((a,b)=>a-b);
  let start = (decades[0] || 1250) - 30;
  let end = (decades[decades.length-1] || 1320) + 40;
  DATA.artists.forEach(a => {
    if (a.born) start = Math.min(start, a.born - 5);
    if (a.died) end = Math.max(end, a.died + 5);
  });
  start = Math.floor(start / 10) * 10;
  end = Math.ceil(end / 10) * 10;
  return {start, end};
}

function centuries(){
  if (DATA.centuries && DATA.centuries.length) return DATA.centuries.slice().sort((a,b)=>a-b);
  const r = yearRange();
  const out = [];
  for (let c = Math.floor(r.start/100)*100; c < r.end; c += 100) out.push(c);
  return out;
}

function centuryLabel(c){
  // 1200 -> "13th c."
  const n = Math.floor(c/100) + 1;
  const suf = (n%10===1&&n%100!==11)?'st':(n%10===2&&n%100!==12)?'nd':(n%10===3&&n%100!==13)?'rd':'th';
  return n + suf + ' c.';
}

function xOf(year, range){ return (year - range.start) * pxPerYear; }
function wOf(y0, y1, range){ return Math.max(36, (y1 - y0) * pxPerYear); }

function decadeOf(y){
  const n = Number(y);
  const decades = DATA.decades || [];
  if (!decades.length) return Math.floor(n/10)*10;
  if (n < decades[0]) return decades[0];
  if (n >= decades[decades.length-1]) return decades[decades.length-1];
  return Math.floor(n / 10) * 10;
}

function pickDecadeHeroes(){
  const rank = {painting:0, sculpture:1, architecture:2, music:3, antiquity:4};
  const byDec = {};
  DATA.artists.forEach(a => {
    a.works.forEach(w => {
      if (!w.file) return; // rail needs a picture
      const d = decadeOf(w.year);
      const score = (a.famous === w.id ? 0 : 10) + (rank[a.medium] ?? 9);
      const prev = byDec[d];
      if (!prev || score < prev.score) byDec[d] = {score, artist:a, work:w};
    });
  });
  return byDec;
}

function packLanes(items){
  const lanes = [];
  items.forEach(it => {
    let placed = false;
    for (let i=0;i<lanes.length;i++){
      if (lanes[i] <= it.start){
        lanes[i] = it.end + 1;
        it.lane = i; placed = true; break;
      }
    }
    if (!placed){ it.lane = lanes.length; lanes.push(it.end + 1); }
  });
  return lanes.length;
}

function boot(){
  try { if ('scrollRestoration' in history) history.scrollRestoration = 'manual'; } catch (e) {}

  const range = yearRange();
  const years = range.end - range.start;
  const avail = Math.max(900, (window.innerWidth || 900) - 48);
  pxPerYear = Math.max(10, Math.min(18, avail / years));
  document.documentElement.style.setProperty('--px-per-year', pxPerYear + 'px');

  setupCenturyMenu();

  draw(range);
  scrollToStart();
  $('#stage').addEventListener('scroll', syncNav, {passive:true});
  $('#panel-x').onclick = closePanel;
  $('#light-x').onclick = closeLight;
  $('#lightbox').addEventListener('click', e => { if (e.target.id === 'lightbox') closeLight(); });
  document.addEventListener('keydown', onKey);
  $('#stage').addEventListener('click', e => {
    if (e.target.closest('.life-line')) return;
    if (e.target.closest('#decade-rail')) {
      const cell = e.target.closest('#decade-rail > div');
      if (cell && cell.style.cursor === 'pointer') return;
    }
    if (e.target.closest('#legend')) return;
    if (e.target.closest('#legend-dock')) return;
    if (e.target.closest('#chrome-dock')) return;
    if (e.target.closest('#artist-panel')) return;
    if (e.target.closest('#lightbox')) return;
    if (!$('#artist-panel').hidden) closePanel();
    clearMediumFilter();
  });
  document.addEventListener('click', e => {
    if ($('#artist-panel').hidden) return;
    if (e.target.closest('#artist-panel')) return;
    if (e.target.closest('#stage')) return;
    if (e.target.closest('#lightbox')) return;
    if (e.target.closest('#legend') || e.target.closest('#legend-dock') || e.target.closest('#chrome-dock')) return;
    if (e.target.closest('#century-pick')) return;
    closePanel();
  });
}

function draw(range){
  const width = (range.end - range.start) * pxPerYear;
  const paper = $('#paper');
  paper.style.width = (width + 48) + 'px';

  const rail = $('#decade-rail');
  rail.innerHTML = '';
  rail.style.width = width + 'px';
  const heroes = pickDecadeHeroes();
  const decades = DATA.decades || [];
  decades.forEach((d, i) => {
    const next = decades[i+1] || Math.min(range.end, d + 10);
    const cell = document.createElement('div');
    cell.className = 'decade-cell';
    cell.style.left = xOf(d, range) + 'px';
    cell.style.width = wOf(d, next, range) + 'px';
    const hero = heroes[d];
    const img = hero ? hero.work.file : '';
    const alt = hero ? hero.work.title : String(d);
    cell.innerHTML = `<div class="shot">${img ? `<img src="${img}" alt="${alt}" loading="lazy">` : ''}</div>
      <div class="decade-num">${d}</div>`;
    if (hero){
      cell.title = `${hero.work.title} — ${hero.artist.name}`;
      cell.style.cursor = 'pointer';
      cell.addEventListener('click', e => {
        e.stopPropagation();
        selectArtistSpan(hero.artist, range);
        openPanel(hero.artist, hero.work);
      });
    }
    rail.appendChild(cell);
  });

  const axis = $('#axis');
  axis.innerHTML = '';
  axis.style.width = width + 'px';
  for (let y = range.start; y <= range.end; y += 10){
    const t = document.createElement('div');
    t.className = 'tick' + (y % 50 === 0 ? ' major' : '');
    t.style.left = xOf(y, range) + 'px';
    axis.appendChild(t);
    if (y % 20 === 0 || decades.includes(y)){
      const lab = document.createElement('div');
      lab.className = 'tick-label';
      lab.style.left = xOf(y, range) + 'px';
      lab.textContent = y;
      axis.appendChild(lab);
    }
  }

  const lanesEl = $('#lanes');
  lanesEl.innerHTML = '';
  lanesEl.style.width = width + 'px';
  const glow = document.createElement('div');
  glow.className = 'span-glow';
  glow.id = 'span-glow';
  lanesEl.appendChild(glow);

  Object.keys(colorCursor).forEach(k => colorCursor[k]=0);

  const items = DATA.artists.map(a => {
    let start = Number(a.born) || decadeOf((a.works[0]||{}).year);
    let end = Number(a.died) || (start + 20);
    if (end < start) end = start + 10;
    const kind = a.medium === 'architecture' ? 'build'
      : a.medium === 'antiquity' ? 'antique'
      : a.medium === 'music' ? 'music' : 'life';
    return { artist:a, start, end, color: colorFor(a.medium), kind };
  }).sort((a,b) => a.start - b.start || a.end - b.end);

  const laneCount = packLanes(items);
  for (let i=0;i<laneCount;i++){
    const lane = document.createElement('div');
    lane.className = 'lane';
    lane.dataset.lane = i;
    lanesEl.appendChild(lane);
  }

  items.forEach(it => {
    const lane = lanesEl.querySelector(`.lane[data-lane="${it.lane}"]`);
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'life-line ' + it.kind;
    el.dataset.medium = it.artist.medium;
    el.style.left = xOf(it.start, range) + 'px';
    el.style.width = wOf(it.start, it.end, range) + 'px';
    el.style.background = it.color;
    el.title = `${it.artist.nameFull} (${it.artist.dates})`;
    el.innerHTML = `<span class="line-label">${escapeHtml(it.artist.name)}<span class="yrs">(${escapeHtml(it.artist.dates)})</span></span>`;
    el.addEventListener('click', e => {
      e.stopPropagation();
      selectLine(it, range);
    });
    lane.appendChild(el);
    it.el = el;
  });

  const dock = $('#legend-dock');
  const leg = document.createElement('div');
  leg.className = 'legend';
  leg.id = 'legend';
  leg.innerHTML = `
    <button type="button" data-filter="painting"><i style="background:#3d5a45"></i> Painting</button>
    <button type="button" data-filter="sculpture"><i style="background:#8a4b32"></i> Sculpture</button>
    <button type="button" data-filter="architecture"><i style="background:#2a3d6b"></i> Architecture</button>
    <button type="button" data-filter="music"><i style="background:#5a3d6b"></i> Music</button>
    <button type="button" data-filter="antiquity"><i style="background:#c4a35a;border:1px dashed #fff8"></i> Ancient model</button>`;
  if (dock){ dock.innerHTML = ''; dock.appendChild(leg); }
  else { lanesEl.appendChild(leg); }
  leg.querySelectorAll('[data-filter]').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      toggleMediumFilter(btn.dataset.filter);
    });
  });

  window.__timeline = {range, items};
}

function clearMediumFilter(){
  const lanesEl = $('#lanes');
  if (!lanesEl) return;
  ['painting','sculpture','architecture','antiquity','music'].forEach(m => lanesEl.classList.remove('filter-'+m));
  document.querySelectorAll('#legend [data-filter]').forEach(b => b.classList.remove('on'));
}

function toggleMediumFilter(medium){
  const lanesEl = $('#lanes');
  if (!lanesEl) return;
  const cls = 'filter-' + medium;
  const already = lanesEl.classList.contains(cls);
  clearMediumFilter();
  if (!already){
    lanesEl.classList.add(cls);
    const btn = document.querySelector('#legend [data-filter="'+medium+'"]');
    if (btn) btn.classList.add('on');
  }
}

function selectArtistSpan(artist, range){
  const items = (window.__timeline && window.__timeline.items) || [];
  const it = items.find(x => x.artist.id === artist.id);
  if (it) selectLine(it, range || window.__timeline.range);
}

function selectLine(it, range){
  const lanesEl = $('#lanes');
  lanesEl.classList.add('is-focus');
  lanesEl.querySelectorAll('.life-line').forEach(el => el.classList.toggle('on', el === it.el));
  const glow = $('#span-glow');
  glow.style.left = xOf(it.start, range) + 'px';
  glow.style.width = wOf(it.start, it.end, range) + 'px';
  openPanel(it.artist);
}

function pinLeft(){
  const st = $('#stage');
  if (!st) return;
  st.scrollLeft = 0;
  st.scrollTop = 0;
  try { st.scrollTo(0, 0); } catch (e) {}
}
function scrollToStart(){
  pinLeft();
  requestAnimationFrame(() => {
    pinLeft();
    requestAnimationFrame(pinLeft);
  });
  setTimeout(pinLeft, 60);
  setTimeout(pinLeft, 250);
  window.addEventListener('load', pinLeft, {once:true});
  syncNav();
}

function scrollToYear(year){
  const range = (window.__timeline && window.__timeline.range) || yearRange();
  const st = $('#stage');
  const x = xOf(year, range) - st.clientWidth * 0.25;
  st.scrollTo({left: Math.max(0, x), behavior:'smooth'});
  syncNav();
}

let centuryValue = null;

function setupCenturyMenu(){
  const menu = $('#century-menu');
  const trigger = $('#century-trigger');
  const label = $('#century-label');
  if (!menu || !trigger || !label) return;
  const cents = centuries();
  centuryValue = cents[0] || 1200;
  menu.innerHTML = '';
  cents.forEach(c => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'century-opt';
    btn.role = 'option';
    btn.dataset.value = String(c);
    btn.textContent = centuryLabel(c);
    btn.setAttribute('aria-selected', c === centuryValue ? 'true' : 'false');
    btn.addEventListener('click', () => {
      setCentury(c, true);
      closeCenturyMenu();
    });
    menu.appendChild(btn);
  });
  label.textContent = centuryLabel(centuryValue);
  trigger.addEventListener('click', e => {
    e.stopPropagation();
    toggleCenturyMenu();
  });
  document.addEventListener('click', e => {
    if (!e.target.closest('#century-pick')) closeCenturyMenu();
  });
}

function setCentury(c, scroll){
  const cents = centuries();
  if (!cents.includes(c)) return;
  centuryValue = c;
  const label = $('#century-label');
  if (label) label.textContent = centuryLabel(c);
  document.querySelectorAll('#century-menu .century-opt').forEach(btn => {
    btn.setAttribute('aria-selected', btn.dataset.value === String(c) ? 'true' : 'false');
  });
  if (scroll) scrollToYear(c + 50);
}

function openCenturyMenu(){
  const menu = $('#century-menu');
  const trigger = $('#century-trigger');
  if (!menu || !trigger) return;
  menu.hidden = false;
  trigger.setAttribute('aria-expanded', 'true');
}
function closeCenturyMenu(){
  const menu = $('#century-menu');
  const trigger = $('#century-trigger');
  if (!menu || !trigger) return;
  menu.hidden = true;
  trigger.setAttribute('aria-expanded', 'false');
}
function toggleCenturyMenu(){
  const menu = $('#century-menu');
  if (!menu) return;
  if (menu.hidden) openCenturyMenu();
  else closeCenturyMenu();
}

function syncNav(){
  const range = (window.__timeline && window.__timeline.range) || yearRange();
  const st = $('#stage');
  const mid = st.scrollLeft + st.clientWidth * 0.35;
  const year = range.start + mid / pxPerYear;
  const cents = centuries();
  let c = Math.floor(year / 100) * 100;
  if (cents.length){
    if (c < cents[0]) c = cents[0];
    if (c > cents[cents.length-1]) c = cents[cents.length-1];
  }
  if (centuryValue !== c) setCentury(c, false);
}

function openPanel(a, focusWork){
  openArtist = a;
  const pan = $('#artist-panel');
  let html = `<h2>${escapeHtml(a.nameFull)}</h2>
    <p class="dates">${escapeHtml(a.dates)} · ${escapeHtml(a.place||'')}</p>`;

  const isMusic = a.medium === 'music';
  const imageWorks = a.works.filter(w => w.file);
  const linkedMusic = isMusic ? a.works.filter(w => (w.listen && w.listen.length) || w.about) : [];
  const textMusic = isMusic ? a.works.filter(w => !(w.listen && w.listen.length) && !w.about && !w.file) : [];
  // music works that have listen OR about, even if they also have a file — list as links; portraits alone stay in image grid
  const linkedIds = new Set(linkedMusic.map(w => w.id));

  if (!isMusic){
    html += `<div class="works">`;
    a.works.forEach(w => {
      const hot = focusWork && focusWork.id === w.id ? ' style="outline:2px solid #9c2b1a"' : '';
      const noImg = !w.file;
      if (!w.file && !w.listen && !w.about){
        // should not look like a button
        return;
      }
      if (!w.file && (w.listen || w.about)){
        const href = (w.listen && w.listen[0] && w.listen[0].url) || w.about;
        html += `<a class="work-link-card" href="${escapeAttr(href)}" target="_blank" rel="noopener noreferrer"${hot}><figcaption><b>${escapeHtml(w.title)}</b><br>${escapeHtml(w.date||'')}<br>${escapeHtml(w.place||'')}</figcaption></a>`;
        return;
      }
      html += `<button type="button" class="${noImg?'no-img':''}" data-work="${w.id}"${hot}>`;
      if (w.file) html += `<img src="${escapeAttr(w.file)}" alt="" loading="lazy">`;
      html += `<figcaption><b>${escapeHtml(w.title)}</b><br>${escapeHtml(w.date||'')}<br>${escapeHtml(w.place||'')}</figcaption></button>`;
    });
    html += `</div>`;
  } else {
    // portraits / manuscript images (optional)
    const portraits = imageWorks.filter(w => !linkedIds.has(w.id) || !(w.listen && w.listen.length));
    // show image grid only for items that are primarily images without listen? If has listen, prefer link list.
    const pureImages = a.works.filter(w => w.file && !(w.listen && w.listen.length) && !w.about);
    if (pureImages.length){
      html += `<div class="works">`;
      pureImages.forEach(w => {
        const hot = focusWork && focusWork.id === w.id ? ' style="outline:2px solid #9c2b1a"' : '';
        html += `<button type="button" data-work="${w.id}"${hot}>`;
        html += `<img src="${escapeAttr(w.file)}" alt="" loading="lazy">`;
        html += `<figcaption><b>${escapeHtml(w.title)}</b><br>${escapeHtml(w.date||'')}<br>${escapeHtml(w.place||'')}</figcaption></button>`;
      });
      html += `</div>`;
    }
    const withLink = a.works.filter(w => (w.listen && w.listen.length) || w.about);
    const plain = a.works.filter(w => !(w.listen && w.listen.length) && !w.about && !w.file);
    // plain may include pureImages titles — list compositions once: linked first, then plain text for the rest (skip duplicates already shown only as images if title-only wanted)
    // User asked: playable/external as links; otherwise plain text list — not buttons.
    html += `<ul class="works-text">`;
    withLink.forEach(w => {
      const href = (w.listen && w.listen[0] && w.listen[0].url) || w.about;
      const extra = [w.date, w.place].filter(Boolean).join(' · ');
      html += `<li><a href="${escapeAttr(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(w.title)}</a>`;
      if (extra) html += ` <span class="work-meta">${escapeHtml(extra)}</span>`;
      // further listen targets
      if (w.listen && w.listen.length > 1){
        w.listen.slice(1).forEach(L => {
          html += ` · <a href="${escapeAttr(L.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(L.label || 'recording')}</a>`;
        });
      }
      html += `</li>`;
    });
    plain.forEach(w => {
      // if this was only a portrait image work with no separate composition name needed, still list title as text (not button)
      const extra = [w.date, w.place].filter(Boolean).join(' · ');
      html += `<li><span class="work-plain">${escapeHtml(w.title)}</span>`;
      if (extra) html += ` <span class="work-meta">${escapeHtml(extra)}</span>`;
      html += `</li>`;
    });
    html += `</ul>`;
  }

  const workQuotes = a.works.filter(w => w.vasari && w.vasari.text);
  if (workQuotes.length){
    html += `<div class="vasari-works">`;
    workQuotes.forEach(w => {
      const V = w.vasari;
      html += `<details class="vasari"><summary>Vasari on <em>${escapeHtml(w.title)}</em></summary>`;
      html += `<blockquote>${escapeHtml(V.text).replace(/\n\n/g,'</blockquote><blockquote>')}</blockquote>`;
      if (V.cite) html += `<p class="cite">${escapeHtml(V.cite)}</p>`;
      html += `</details>`;
    });
    html += `</div>`;
  } else if (a.vasari && a.vasari.text){
    html += `<details class="vasari"><summary>Vasari · ${escapeHtml(a.vasari.life||'Life')}</summary>
      <blockquote>${escapeHtml(a.vasari.text).replace(/\n\n/g,'</blockquote><blockquote>')}</blockquote>
      <p class="cite">${escapeHtml(a.vasari.cite||'')}</p></details>`;
  }
  if (a.vasari && a.vasari.url){
    const of = a.vasari.of || a.nameFull || a.name;
    html += `<div class="vasari-complete">
      <p class="vasari-complete-kicker">Complete Text of Vasari's Life of ${escapeHtml(of)}</p>
      <p class="vasari-complete-link"><a href="${escapeAttr(a.vasari.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(a.vasari.life || "Vasari's Life")}</a></p>
    </div>`;
  }
  $('#panel-body').innerHTML = html;
  pan.hidden = false;
  pan.querySelectorAll('[data-work]').forEach(btn => {
    btn.addEventListener('click', () => {
      const w = a.works.find(x => x.id === btn.dataset.work);
      if (w && w.file) openLight(a, w);
    });
  });
}

function closePanel(){
  $('#artist-panel').hidden = true;
  openArtist = null;
  const lanesEl = $('#lanes');
  if (lanesEl){
    lanesEl.classList.remove('is-focus');
    lanesEl.querySelectorAll('.life-line.on').forEach(el => el.classList.remove('on'));
  }
}

function openLight(a, w){
  if (!w.file) return;
  $('#light-img').src = w.file;
  $('#light-img').alt = w.title;
  $('#light-cap').textContent = `${w.title}, ${w.date}. ${w.place||''} — ${a.nameFull}.`;
  $('#lightbox').hidden = false;
}

function closeLight(){
  $('#lightbox').hidden = true;
  $('#light-img').src = '';
}

function onKey(e){
  if (e.key === 'Escape'){
    if (!$('#lightbox').hidden) { closeLight(); return; }
    if (!$('#artist-panel').hidden) { closePanel(); return; }
    clearMediumFilter();
  }
  if (e.key === 'ArrowRight' || e.key === 'ArrowLeft'){
    const cents = centuries();
    if (!cents.length) return;
    const on = cents.indexOf(centuryValue);
    const idx = on < 0 ? 0 : on;
    const n = e.key === 'ArrowRight' ? idx+1 : idx-1;
    if (n>=0 && n<cents.length){
      setCentury(cents[n], true);
      closeCenturyMenu();
    }
  }
}

function escapeHtml(s){
  return String(s).replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
}
function escapeAttr(s){
  return String(s).replace(/[&"<>]/g, c => ({'&':'&amp;','"':'&quot;','<':'&lt;','>':'&gt;'}[c]));
}

boot();
